// Stages one mod as an npm package: `node .github/scripts/build-npm-package.mjs <mod> <outDir>`.
//
// The mods are not npm packages in the repo: no folder holds a package.json, so
// Claude Code never mistakes a relative-path install for one that needs its
// dependencies installed, and there is no second copy of each version to keep
// in step. This script writes the package.json at publish time instead, from
// the mod's own .claude-plugin/plugin.json, and copies the mod beside it
// without its tests, test runs and tooling.
//
// The package root is the plugin root, which is what a marketplace entry with
// an npm source expects: .claude-plugin/plugin.json and hooks/ sit at the top.
import { cpSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const SCOPE = '@afterever'
const REPO = 'https://github.com/afterever/claude-craftkits'

// Paths (relative to the mod) and name patterns that stay out of the package.
const LEFT_OUT = [
  /(^|\/)node_modules(\/|$)/,
  /(^|\/)\.claude-plugin\/types(\/|$)/, // regenerated by Claude Code on load
  /(^|\/)\.claude\/types(\/|$)/,
  /(^|\/)tests?(\/|$)/,
  /(^|\/)test-runs(\/|$)/,
  /(^|\/)media-src(\/|$)/,
  /\.test\.[cm]?[jt]sx?$/,
  /(^|\/)tsconfig\.json$/,
  /(^|\/)package(-lock)?\.json$/,
  /(^|\/)\.gitignore$/,
]

export function buildPackage(mod, outDir, root = process.cwd()) {
  if (!/^[a-z][a-z0-9-]*$/.test(mod)) throw new Error(`"${mod}" is not a mod name`)
  const src = join(root, mod)
  const manifestPath = join(src, '.claude-plugin', 'plugin.json')
  if (!existsSync(manifestPath)) throw new Error(`${mod} has no .claude-plugin/plugin.json`)

  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'))
  if (manifest.name !== mod) throw new Error(`${mod}: plugin.json names it "${manifest.name}"`)
  if (!/^\d+\.\d+\.\d+$/.test(manifest.version ?? '')) throw new Error(`${mod}: plugin.json has no x.y.z version`)

  rmSync(outDir, { recursive: true, force: true })
  mkdirSync(outDir, { recursive: true })
  cpSync(src, outDir, {
    recursive: true,
    filter: path => !LEFT_OUT.some(re => re.test(path.slice(src.length + 1).replaceAll('\\', '/'))),
  })

  // The repo's own licence covers a mod that has none of its own.
  if (!existsSync(join(outDir, 'LICENSE'))) cpSync(join(root, 'LICENSE'), join(outDir, 'LICENSE'))

  const pkg = {
    name: `${SCOPE}/${mod}`,
    version: manifest.version,
    description: manifest.description,
    license: manifest.license ?? 'MIT',
    author: manifest.author?.name,
    repository: { type: 'git', url: `git+${REPO}.git`, directory: mod },
    homepage: `${REPO}/tree/master/${mod}#readme`,
    keywords: ['claude-code', 'claude-code-plugin', 'claude-code-mod'],
    publishConfig: { access: 'public' },
  }
  writeFileSync(join(outDir, 'package.json'), JSON.stringify(pkg, null, 2) + '\n')
  return pkg
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const [mod, outDir] = process.argv.slice(2)
  if (!mod || !outDir) {
    console.error('usage: node .github/scripts/build-npm-package.mjs <mod> <outDir>')
    process.exit(2)
  }
  try {
    const pkg = buildPackage(mod, resolve(outDir))
    console.log(`${pkg.name}@${pkg.version} staged in ${outDir}`)
  } catch (e) {
    console.error(e.message)
    process.exit(1)
  }
}
